const $=s=>document.querySelector(s);
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<65;i++){const p=document.createElement('i');p.className='confetti';p.style.left=Math.random()*100+'vw';p.style.background=['#ed633e','#efc8d2','#dfe6b8','#243c31','#f1b744'][i%5];p.style.animationDelay=Math.random()*.7+'s';p.style.animationDuration=(2+Math.random()*2)+'s';document.body.append(p);setTimeout(()=>p.remove(),5000)}}
$('#party').addEventListener('click',()=>{confetti();toast('Perayaan dimulai! Lisa wajib bahagia. Admin wajib cari kue. 🎂')});
const wishes=['Semoga bahagia lo nggak cuma buat postingan, tapi beneran kerasa sampai ke hati.','Semoga sehat terus, tidur cukup, dan alarm pagi nggak jadi musuh bebuyutan.','Semoga rezekinya lancar. Pas cek saldo, senyumnya tulus, bukan senyum bertahan hidup.','Semoga hal yang lagi lo usahain nemu jalan. Pelan juga nggak apa-apa, yang penting tetap melangkah.','Semoga dikelilingi orang baik yang hadirnya bikin tenang, bukan bikin baterai sosial lowbat.','Semoga makin sayang sama diri sendiri. Istirahat itu hak, bukan hadiah setelah capek banget.','Semoga hari-hari lo penuh kabar baik, makanan enak, dan paket yang ongkirnya gratis.','Semoga semua doa baik lo ketemu waktu terbaiknya. Happy birthday, Lisa!'];let wishIndex=0;
$('#wish-button').addEventListener('click',()=>{wishIndex=(wishIndex+1)%wishes.length;$('#wish').textContent=wishes[wishIndex];$('#wish-count').textContent=`DOA ${String(wishIndex+1).padStart(2,'0')} / 08`});
const dialog=$('#photo-dialog');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{$('#dialog-image').src='assets/'+b.dataset.photo;$('#dialog-image').alt=b.querySelector('img').alt;$('#dialog-caption').textContent=b.dataset.caption;dialog.showModal()}));$('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('#candle').addEventListener('click',()=>{if($('#candle').classList.contains('blown'))return;$('#candle').classList.add('blown');$('#candle').setAttribute('aria-label','Lilin sudah padam');$('#cake-message').textContent='Aamiin! Semoga harapan lo ketemu jalan terbaiknya. 🎉';$('#relight').hidden=false;confetti()});$('#relight').addEventListener('click',()=>{$('#candle').classList.remove('blown');$('#candle').setAttribute('aria-label','Tiup lilin ulang tahun');$('#cake-message').textContent='Oke, satu harapan lagi. Nggak ada batas maksimal kok.';$('#relight').hidden=true});
